    // src/components/AddFlower.js
    import React, { useState } from "react";
    import axios from "axios";
    import { toast } from "react-toastify";
    import "./AddFlower.css"; // external styles

    function AddFlower() {
    const [formData, setFormData] = useState({
        name: "",
        description: "",
        price: "",
        category: "",
        image: null,
    });
    
    // Handle input fields
    const handleChange = (e) => {
        if (e.target.name === "image") {
        setFormData({ ...formData, image: e.target.files[0] });
        } else {
        setFormData({ ...formData, [e.target.name]: e.target.value });
        }
    };

    // Submit form
    const handleSubmit = async (e) => {
        e.preventDefault();

        try {
        const data = new FormData();
        data.append("name", formData.name);
        data.append("description", formData.description);
        data.append("price", formData.price);
        data.append("category", formData.category);
        if (formData.image) data.append("image", formData.image);

        const res = await axios.post("http://localhost:3001/api/flowers", data, {
            headers: { "Content-Type": "multipart/form-data" },
        });

        setMessage(" Flower added successfully!");
        toast.success(" Flower added successfully!");
        console.log("Saved flower:", res.data);

    const [message, setMessage] = useState('');

        // Reset form
        setFormData({
            name: "",
            description: "",
            price: "",
            category: "",
            image: null,
        });
        } catch (err) {
        console.error(err);
        setMessage(" Failed to add flower.");
        toast.error(" Failed to add flower.");
        }
    };

    return (
        <div className="add-flower">
        <h2>Add Flower</h2>
        <form onSubmit={handleSubmit} className="add-flower-form">
            <input
            type="text"
            name="name"
            placeholder="Flower Name"
            value={formData.name}
            onChange={handleChange}
            required
            />
            <textarea
            name="description"
            placeholder="Description"
            value={formData.description}
            onChange={handleChange}
            required
            />
            <input
            type="number"
            name="price"
            placeholder="Price"
            value={formData.price}
            onChange={handleChange}
            required
            />
            <input
            type="text"
            name="category"
            placeholder="Category"
            value={formData.category}
            onChange={handleChange}
            required
            />
            <input type="file" name="image" accept="image/*" onChange={handleChange} />

            <button type="submit">Add Flower</button>
        </form>

        </div>
    );
    }

    export default AddFlower;
